// `tags` arrives from the search API as a JSON array in a string.
const tagsOf = (value) => {
  if (Array.isArray(value)) return value;
  try { return JSON.parse(value || '[]'); } catch { return []; }
};
context.handlebars.registerHelper('has', (tags, tag) => tagsOf(tags).includes(tag));
// The chips of a card: its theme and engine tags; `kepler` is every card and
// `plus` is the section, and the Business plugins are not what a visitor picks by.
context.handlebars.registerHelper('chips', (tags) => tagsOf(tags).filter((t) => !['kepler', 'plus', 'business-charts', 'business-table', 'business-text', 'business-variable'].includes(t)));
context.handlebars.registerHelper('tagged', (rows, tag) => (rows || []).filter((r) => tagsOf(r.tags).includes(tag)).length);
context.handlebars.registerHelper('inFolder', (rows, uid) => (rows || []).filter((r) => r.folderUid === uid).length);

options.styles:
@font-face { font-family: Outfit; src: url(/home/assets/outfit.woff2) format('woff2'); font-weight: 400 700; font-style: normal; font-display: swap; }
.pacha { --ink: #0F2327; --ink-2: #132C31; --ink-3: #0C1E22; --teal: #0B8278; --teal-hi: #10A396; --mint: #9FE3D7; --moss: #5FA39A; --text: #FFFFFF; --text-2: #C5D9D5; --muted: #8FB3AD; --line: rgba(159, 227, 215, .14); color: var(--text); background: var(--ink); border-radius: 2px; height: 100%; overflow: hidden; }
.pacha h1, .pacha h2, .pacha h3 { font-family: Outfit, Inter, ui-sans-serif, system-ui, sans-serif; margin: 0; color: var(--text); }
.pacha p { margin: 0; }
.pacha a { color: var(--mint); text-decoration: none; }
.pacha a:hover { color: var(--text); }
.pacha .wrap { max-width: 1240px; margin: 0 auto; padding: 0 32px; }
.pacha .eyebrow { font-size: 12px; font-weight: 600; letter-spacing: .1em; text-transform: uppercase; color: var(--mint); }
.pacha .go { display: inline-flex; align-items: center; justify-content: center; gap: 8px; min-height: 42px; padding: 0 18px; border-radius: 8px; border: 1px solid rgba(159, 227, 215, .3); background: rgba(255, 255, 255, .04); color: var(--text); font-weight: 500; font-size: 15px; transition: background .15s ease, border-color .15s ease; }
.pacha .go:hover { background: rgba(159, 227, 215, .12); border-color: rgba(159, 227, 215, .55); color: var(--text); }
.pacha .go.primary { background: var(--teal); border-color: var(--teal); }
.pacha .go.primary:hover { background: var(--teal-hi); border-color: var(--teal-hi); }
.pacha .go-row { display: flex; flex-wrap: wrap; gap: 10px; }
.pacha .chips { display: flex; flex-wrap: wrap; gap: 6px; }
.pacha .chip { display: inline-flex; align-items: center; font-size: 13px; line-height: 1; padding: 7px 11px; border-radius: 999px; border: 1px solid rgba(159, 227, 215, .25); color: var(--text-2); background: rgba(255, 255, 255, .03); }
.pacha .chip:hover { border-color: rgba(159, 227, 215, .6); color: var(--text); }
.pacha .chip.on { background: var(--teal); border-color: var(--teal); color: var(--text); }
.pacha .section-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: 10px 24px; }
.pacha .section-head h2 { font-size: 30px; font-weight: 600; letter-spacing: -.015em; line-height: 1.1; }
.pacha .section-head p { font-size: 15px; color: var(--text-2); margin-top: 4px; }
.pacha .section-head .more { font-size: 15px; font-weight: 500; }
@media (max-width: 640px) { .pacha .wrap { padding: 0 16px; } }
.pacha.promo-panel { background: transparent; }
.promo { display: flex; flex-wrap: wrap; gap: 24px 40px; align-items: center; padding: 28px 32px; border-radius: 14px; background: var(--ink-2); border: 1px solid rgba(159, 227, 215, .2); }
.promo-text { flex: 1 1 440px; min-width: 0; display: flex; flex-direction: column; gap: 14px; }
.promo-text h2 { font-size: 30px; font-weight: 600; letter-spacing: -.015em; line-height: 1.15; }
.promo-text p { font-size: 15px; line-height: 1.5; color: var(--text-2); }
.promo-shot { flex: 1 1 380px; min-width: 0; display: block; border-radius: 10px; overflow: hidden; border: 1px solid rgba(159, 227, 215, .18); }
.promo-shot img { width: 100%; height: auto; display: block; }
.plus-head { padding: 26px 0 0; }
.pacha.promo-panel .wrap { padding: 0; }
